            new Quote { Id = "https://fr.wikiquote.org/wiki/Guy_de_Maupassant", Text = "Eh bien... on y voyait comme en plein jour... et je ne me vis pas dans ma glace ! Elle était vide, claire, profonde, pleine de lumière !", Author = "Guy de Maupassant" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Guy_de_Maupassant", Text = "Non… non… sans aucun doute, sans aucun doute… il n’est pas mort… Alors… alors… il va donc falloir que je me tue, moi !", Author = "Guy de Maupassant" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Guy_de_Maupassant", Text = "Le cœur a des mystères qu’aucun raisonnement ne pénètre.", Author = "Guy de Maupassant" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Guy_de_Maupassant", Text = "La vie, voyez-vous, ça n’est jamais si bon ni si mauvais qu’on croit.", Author = "Guy de Maupassant" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Guy_de_Maupassant", Text = "La vie est une côte. Tant qu’on monte, on regarde le sommet, et on se sent heureux ; mais, lorsqu’on arrive en haut, on aperçoit tout d’un coup la descente, et la fin qui est la mort. Ça va lentement quand on monte, mais ça va vite quand on descend.", Author = "Guy de Maupassant" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Guy_de_Maupassant", Text = "les femmes n’espèrent point toujours autre chose que ce qui est !", Author = "Guy de Maupassant" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Guy_de_Maupassant", Text = "se servir de la religion comme on se sert d’un en-tout-cas. S’il fait beau, c’est une canne ; s’il fait du soleil, c’est une ombrelle ; s’il pleut, c’est un parapluie, et, si on ne sort pas, on le laisse dans l’antichambre.", Author = "Guy de Maupassant" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Guy_de_Maupassant", Text = "les paroles d’amour, qui sont toujours les mêmes, prennent le goût des lèvres dont elles sortent.", Author = "Guy de Maupassant" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Guy_de_Maupassant", Text = "Le réaliste, s’il est un artiste, cherchera, non pas à nous montrer la photographie banale de la vie, mais à nous en donner la vision plus complète, plus saisissante, plus probante que la réalité même.", Author = "Guy de Maupassant" },
